func userFromRow(row lir.Row) User {
	m := User{}
	m.ID = row["id"].Text
	m.Username = row["username"].Text
	m.DisplayName = stringPtr(row["display_name"])
	m.PasswordHash = row["password_hash"].Text
	m.Email = stringPtr(row["email"])
	m.CreatedAt = row["created_at"].Int64
	return m
}

func userFromRecord(rec *frontend.Record) User {
	m := userFromRow(rec.Columns)
	for _, kid := range rec.Children["sessions"] {
		m.Sessions = append(m.Sessions, sessionFromRecord(kid))
	}
	for _, kid := range rec.Children["team_members"] {
		m.TeamMembers = append(m.TeamMembers, teamMemberFromRecord(kid))
	}
	for _, kid := range rec.Children["tasks_by_assignee"] {
		m.TasksByAssignee = append(m.TasksByAssignee, taskFromRecord(kid))
	}
	for _, kid := range rec.Children["tasks_by_creator"] {
		m.TasksByCreator = append(m.TasksByCreator, taskFromRecord(kid))
	}
	for _, kid := range rec.Children["comments"] {
		m.Comments = append(m.Comments, commentFromRecord(kid))
	}
	return m
}

