// All executes the query.
func (q *SessionQuery) All(ctx context.Context) ([]Session, error) {
	if len(q.filters) == 1 {
		q.read.Filter = q.filters[0]
	} else if len(q.filters) > 1 {
		q.read.Filter = lir.And{Exprs: q.filters}
	}
	recs, err := q.v.Read(ctx, q.read)
	if err != nil {
		return nil, err
	}
	out := make([]Session, len(recs))
	for i, r := range recs {
		out[i] = sessionFromRecord(r)
	}
	return out, nil
}

// First executes the query with limit 1.
func (q *SessionQuery) First(ctx context.Context) (Session, bool, error) {
	q.read.Limit = 1
	rows, err := q.All(ctx)
	if err != nil || len(rows) == 0 {
		return Session{}, false, err
	}
	return rows[0], true, nil
}

