func sessionFromRow(row lir.Row) Session {
	m := Session{}
	m.Token = row["token"].Text
	m.UserID = row["user_id"].Text
	m.CreatedAt = row["created_at"].Int64
	m.ExpiresAt = row["expires_at"].Int64
	return m
}

func sessionFromRecord(rec *frontend.Record) Session {
	m := sessionFromRow(rec.Columns)
	if parent := rec.Parents["user"]; parent != nil {
		v := userFromRecord(parent)
		m.User = &v
	}
	return m
}

