func (t TeamTable) Create(ctx context.Context, in TeamCreate) (Team, error) {
	row := lir.Row{}
	if in.ID != nil {
		row["id"] = lir.Text(*in.ID)
	}
	row["name"] = lir.Text(in.Name)
	if in.CreatedAt != nil {
		row["created_at"] = lir.Int64(*in.CreatedAt)
	}
	stored, err := t.v.Create(ctx, "teams", row)
	if err != nil {
		return Team{}, err
	}
	return teamFromRow(stored), nil
}

func (t TeamTable) Get(ctx context.Context, id string) (Team, bool, error) {
	row, ok, err := t.v.Get(ctx, "teams", lir.Row{"id": lir.Text(id)})
	if err != nil || !ok {
		return Team{}, false, err
	}
	return teamFromRow(row), true, nil
}

func (t TeamTable) Update(ctx context.Context, id string, patch TeamPatch) (Team, bool, error) {
	set := lir.Row{}
	if patch.Name != nil {
		set["name"] = lir.Text(*patch.Name)
	}
	if patch.CreatedAt != nil {
		set["created_at"] = lir.Int64(*patch.CreatedAt)
	}
	row, ok, err := t.v.Update(ctx, "teams", lir.Row{"id": lir.Text(id)}, set)
	if err != nil || !ok {
		return Team{}, false, err
	}
	return teamFromRow(row), true, nil
}

