func teamFromRow(row lir.Row) Team {
	m := Team{}
	m.ID = row["id"].Text
	m.Name = row["name"].Text
	m.CreatedAt = row["created_at"].Int64
	return m
}

func teamFromRecord(rec *frontend.Record) Team {
	m := teamFromRow(rec.Columns)
	for _, kid := range rec.Children["team_members"] {
		m.TeamMembers = append(m.TeamMembers, teamMemberFromRecord(kid))
	}
	for _, kid := range rec.Children["boards"] {
		m.Boards = append(m.Boards, boardFromRecord(kid))
	}
	for _, kid := range rec.Children["labels"] {
		m.Labels = append(m.Labels, labelFromRecord(kid))
	}
	return m
}

