func teamMemberFromRow(row lir.Row) TeamMember {
	m := TeamMember{}
	m.TeamID = row["team_id"].Text
	m.UserID = row["user_id"].Text
	m.Role = row["role"].Text
	m.JoinedAt = row["joined_at"].Int64
	return m
}

func teamMemberFromRecord(rec *frontend.Record) TeamMember {
	m := teamMemberFromRow(rec.Columns)
	if parent := rec.Parents["team"]; parent != nil {
		v := teamFromRecord(parent)
		m.Team = &v
	}
	if parent := rec.Parents["user"]; parent != nil {
		v := userFromRecord(parent)
		m.User = &v
	}
	return m
}

