func (b *BoardInclude) IncludeTasks(opts ...func(*TaskInclude)) *BoardInclude {
	nested := &TaskInclude{inc: lir.Include{FK: "tasks_board_id_fk", Dir: lir.ToChildren, As: "tasks"}}
	for _, o := range opts {
		o(nested)
	}
	nested.inc.Filter = nested.filter()
	b.inc.Include = append(b.inc.Include, nested.inc)
	return b
}

func boardFromRow(row lir.Row) Board {
	m := Board{}
	m.ID = row["id"].Text
	m.TeamID = row["team_id"].Text
	m.Name = row["name"].Text
	m.Archived = row["archived"].Bool
	m.CreatedAt = row["created_at"].Int64
	return m
}

func boardFromRecord(rec *frontend.Record) Board {
	m := boardFromRow(rec.Columns)
	if parent := rec.Parents["team"]; parent != nil {
		v := teamFromRecord(parent)
		m.Team = &v
	}
	for _, kid := range rec.Children["tasks"] {
		m.Tasks = append(m.Tasks, taskFromRecord(kid))
	}
	return m
}

