func taskFromRow(row lir.Row) Task {
	m := Task{}
	m.ID = row["id"].Text
	m.BoardID = row["board_id"].Text
	m.Title = row["title"].Text
	m.Description = stringPtr(row["description"])
	m.Status = row["status"].Text
	m.Priority = row["priority"].Int64
	m.Estimate = float64Ptr(row["estimate"])
	m.AssigneeID = stringPtr(row["assignee_id"])
	m.CreatorID = row["creator_id"].Text
	m.ParentID = stringPtr(row["parent_id"])
	m.DueAt = int64Ptr(row["due_at"])
	m.CreatedAt = row["created_at"].Int64
	return m
}

func taskFromRecord(rec *frontend.Record) Task {
	m := taskFromRow(rec.Columns)
	if parent := rec.Parents["board"]; parent != nil {
		v := boardFromRecord(parent)
		m.Board = &v
	}
	if parent := rec.Parents["assignee"]; parent != nil {
		v := userFromRecord(parent)
		m.Assignee = &v
	}
	if parent := rec.Parents["creator"]; parent != nil {
		v := userFromRecord(parent)
		m.Creator = &v
	}
	if parent := rec.Parents["parent"]; parent != nil {
		v := taskFromRecord(parent)
		m.Parent = &v
	}
	for _, kid := range rec.Children["tasks"] {
		m.Tasks = append(m.Tasks, taskFromRecord(kid))
	}
	for _, kid := range rec.Children["comments"] {
		m.Comments = append(m.Comments, commentFromRecord(kid))
	}
	for _, kid := range rec.Children["task_labels"] {
		m.TaskLabels = append(m.TaskLabels, taskLabelFromRecord(kid))
	}
	return m
}

