func commentFromRow(row lir.Row) Comment {
	m := Comment{}
	m.ID = row["id"].Text
	m.TaskID = row["task_id"].Text
	m.AuthorID = row["author_id"].Text
	m.Body = row["body"].Text
	m.CreatedAt = row["created_at"].Int64
	return m
}

func commentFromRecord(rec *frontend.Record) Comment {
	m := commentFromRow(rec.Columns)
	if parent := rec.Parents["task"]; parent != nil {
		v := taskFromRecord(parent)
		m.Task = &v
	}
	if parent := rec.Parents["author"]; parent != nil {
		v := userFromRecord(parent)
		m.Author = &v
	}
	return m
}

