// LabelTable provides typed access to "labels".
type LabelTable struct{ v view }

func (t LabelTable) Create(ctx context.Context, in LabelCreate) (Label, error) {
	row := lir.Row{}
	if in.ID != nil {
		row["id"] = lir.Text(*in.ID)
	}
	row["team_id"] = lir.Text(in.TeamID)
	row["name"] = lir.Text(in.Name)
	if in.HexColor != nil {
		row["hex_color"] = lir.Text(*in.HexColor)
	}
	stored, err := t.v.Create(ctx, "labels", row)
	if err != nil {
		return Label{}, err
	}
	return labelFromRow(stored), nil
}

func (t LabelTable) Get(ctx context.Context, id string) (Label, bool, error) {
	row, ok, err := t.v.Get(ctx, "labels", lir.Row{"id": lir.Text(id)})
	if err != nil || !ok {
		return Label{}, false, err
	}
	return labelFromRow(row), true, nil
}

func (t LabelTable) Update(ctx context.Context, id string, patch LabelPatch) (Label, bool, error) {
	set := lir.Row{}
	if patch.TeamID != nil {
		set["team_id"] = lir.Text(*patch.TeamID)
	}
	if patch.Name != nil {
		set["name"] = lir.Text(*patch.Name)
	}
	if patch.HexColor != nil {
		set["hex_color"] = lir.Text(*patch.HexColor)
	}
	row, ok, err := t.v.Update(ctx, "labels", lir.Row{"id": lir.Text(id)}, set)
	if err != nil || !ok {
		return Label{}, false, err
	}
	return labelFromRow(row), true, nil
}

func (t LabelTable) Delete(ctx context.Context, id string) (bool, error) {
	return t.v.Delete(ctx, "labels", lir.Row{"id": lir.Text(id)})
}

// ByTeamIDName finds the row by the unique index on (team_id, name).
func (t LabelTable) ByTeamIDName(ctx context.Context, teamID string, name string) (Label, bool, error) {
	recs, err := t.v.Read(ctx, lir.Read{Table: "labels", Filter: lir.And{Exprs: []lir.Expr{
		lir.Eq{Left: lir.ColRef{Column: "team_id"}, Right: lir.Literal{Value: lir.Text(teamID)}},
		lir.Eq{Left: lir.ColRef{Column: "name"}, Right: lir.Literal{Value: lir.Text(name)}},
	}}, Limit: 1})
	if err != nil || len(recs) == 0 {
		return Label{}, false, err
	}
	return labelFromRecord(recs[0]), true, nil
}

