func (q *LabelQuery) All(ctx context.Context) ([]Label, error) {
	if len(q.filters) == 1 {
		q.read.Filter = q.filters[0]
	} else if len(q.filters) > 1 {
		q.read.Filter = lir.And{Exprs: q.filters}
	}
	recs, err := q.v.Read(ctx, q.read)
	if err != nil {
		return nil, err
	}
	out := make([]Label, len(recs))
	for i, r := range recs {
		out[i] = labelFromRecord(r)
	}
	return out, nil
}

